const originalTextNodes = new WeakMap();
const originalAttributes = new WeakMap();
let currentLanguage = localStorage.getItem("jon-language") === "zh" ? "zh" : "en";

function translatePageText(language) {
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    if (node.parentElement?.closest(".language-switcher")) continue;
    if (!originalTextNodes.has(node)) originalTextNodes.set(node, node.nodeValue);
    const original = originalTextNodes.get(node);
    const key = original.trim();
    if (!key) continue;
    const leading = original.match(/^\s*/)[0];
    const trailing = original.match(/\s*$/)[0];
    node.nodeValue = language === "zh" && translationsZh[key] ? `${leading}${translationsZh[key]}${trailing}` : original;
  }

  document.querySelectorAll("[aria-label], [title], meta[name='description']").forEach((element) => {
    if (!originalAttributes.has(element)) {
      originalAttributes.set(element, {
        ariaLabel: element.getAttribute("aria-label"),
        title: element.getAttribute("title"),
        content: element.getAttribute("content")
      });
    }
    const originals = originalAttributes.get(element);
    ["aria-label", "title", "content"].forEach((attribute) => {
      const key = attribute === "aria-label" ? "ariaLabel" : attribute;
      const original = originals[key];
      if (original === null) return;
      element.setAttribute(attribute, language === "zh" && attributeTranslationsZh[original] ? attributeTranslationsZh[original] : original);
    });
  });
}

function setLanguage(language, persist = true) {
  currentLanguage = language === "zh" ? "zh" : "en";
  document.documentElement.lang = currentLanguage === "zh" ? "zh-CN" : "en";
  document.title = currentLanguage === "zh" ? "张凯淞 — 生成式 AI / 全栈工程师" : "Jon Zhang — GenAI / Full-Stack Engineer";
  translatePageText(currentLanguage);
  document.querySelectorAll(".language-option").forEach((button) => {
    const selected = button.dataset.language === currentLanguage;
    button.classList.toggle("active", selected);
    button.setAttribute("aria-pressed", String(selected));
  });
  if (persist) localStorage.setItem("jon-language", currentLanguage);
}

const toast = document.querySelector("#toast");
let toastTimer;
function showToast(message) {
  toast.textContent = message;
  toast.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove("show"), 3200);
}

